package com.ci.pipeline

import java.util.concurrent.ConcurrentHashMap
import java.security.SecureRandom
import javax.crypto.spec.SecretKeySpec
import javax.crypto.Cipher
import java.util.Base64

object FeatureFlags {
  @volatile private var flags: Map[String, Boolean] = Map(
    "enable_secret_caching" -> true,
    "enable_audit_log" -> true,
    "enable_ephemeral_keys" -> false,
    "gc_sensitive_on_dispose" -> true
  )

  def isEnabled(flag: String): Boolean = flags.getOrElse(flag, false)
  def update(flag: String, value: Boolean): Unit = { flags = flags + (flag -> value) }
}

class SecretVault {
  private val secrets = new ConcurrentHashMap[String, Array[Byte]]()
  private val metadata = new ConcurrentHashMap[String, SecretMetadata]()

  case class SecretMetadata(createdAt: Long, accessCount: Int, ephemeral: Boolean)

  def store(key: String, value: Array[Byte], ephemeral: Boolean = false): Unit = {
    secrets.put(key, value.clone())
    metadata.put(key, SecretMetadata(System.currentTimeMillis(), 0, ephemeral))
  }

  def retrieve(key: String): Option[Array[Byte]] = {
    Option(secrets.get(key)).map { secret =>
      val meta = metadata.get(key)
      metadata.put(key, meta.copy(accessCount = meta.accessCount + 1))
      secret.clone()
    }
  }

  def dispose(key: String): Unit = {
    val secret = secrets.remove(key)
    metadata.remove(key)
    if (secret != null) {
      java.util.Arrays.fill(secret, 0.toByte)
    }
  }
}

class PipelineExecutor(vault: SecretVault) {
  private val executionCache = new ConcurrentHashMap[String, ExecutionContext]()

  case class ExecutionContext(
    pipelineId: String,
    secretCount: Int,
    startTime: Long
  )

  def executePipeline(pipelineId: String, secretKeys: List[String]): Boolean = {
    val resolvedSecrets = new java.util.ArrayList[Array[Byte]]()

    secretKeys.foreach { key =>
      vault.retrieve(key) match {
        case Some(secret) => resolvedSecrets.add(secret)
        case None => return false
      }
    }

    val ctx = ExecutionContext(pipelineId, resolvedSecrets.size(), System.currentTimeMillis())

    if (FeatureFlags.isEnabled("enable_secret_caching")) {
      executionCache.put(pipelineId, ctx)
    }

    try {
      runStages(resolvedSecrets)
    } finally {
      resolvedSecrets.forEach { secret =>
        java.util.Arrays.fill(secret, 0.toByte)
      }
      resolvedSecrets.clear()
      cleanupContext(pipelineId)
    }
  }

  private def runStages(secrets: java.util.List[Array[Byte]]): Boolean = {
    // Simulate pipeline stages
    Thread.sleep(10)
    true
  }

  private def cleanupContext(pipelineId: String): Unit = {
    executionCache.remove(pipelineId)
  }

  def getActivePipelines: java.util.Set[String] = {
    executionCache.keySet()
  }

  def inspectCache(pipelineId: String): Option[ExecutionContext] = {
    Option(executionCache.get(pipelineId))
  }
}

class DeploymentOrchestrator {
  private val vault = new SecretVault()
  private val executor = new PipelineExecutor(vault)
  private val completedRuns = new java.util.ArrayList[CompletedRun]()

  case class CompletedRun(pipelineId: String, secretCount: Int, timestamp: Long)

  def deploy(pipelineId: String, secretKeys: List[String]): Boolean = {
    val result = executor.executePipeline(pipelineId, secretKeys)

    if (FeatureFlags.isEnabled("enable_audit_log")) {
      recordCompletion(pipelineId, secretKeys.size)
    }

    result
  }

  private def recordCompletion(pipelineId: String, secretCount: Int): Unit = {
    completedRuns.add(CompletedRun(pipelineId, secretCount, System.currentTimeMillis()))
    pruneOldRuns()
  }

  private def pruneOldRuns(): Unit = {
    val cutoff = System.currentTimeMillis() - 3600000
    completedRuns.removeIf(run => run.timestamp < cutoff)
  }

  def setupSecrets(pairs: Map[String, Array[Byte]]): Unit = {
    pairs.foreach { case (k, v) =>
      vault.store(k, v, ephemeral = FeatureFlags.isEnabled("enable_ephemeral_keys"))
    }
  }

  def getCompletedRunCount: Int = completedRuns.size()
}
